-- ----------------------------
-- Table structure for  prerequisite
-- ----------------------------
DROP TABLE IF EXISTS ` prerequisite`;
CREATE TABLE ` prerequisite`  (
  `PrerequisiteID` int NOT NULL,
  `CourseID` int NOT NULL,
  `Type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`CourseID`) USING BTREE,
  INDEX `fk_PrerequisiteID`(`PrerequisiteID` ASC) USING BTREE,
  CONSTRAINT ` fk_CourseID` FOREIGN KEY (`CourseID`) REFERENCES `courses` (`CourseID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_PrerequisiteID` FOREIGN KEY (`PrerequisiteID`) REFERENCES `courses` (`CourseID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

