-- ----------------------------
-- Table structure for enrollment
-- ----------------------------
DROP TABLE IF EXISTS `enrollment`;
CREATE TABLE `enrollment`  (
  `EnrollmentID` int NOT NULL,
  `StudentID` int NOT NULL,
  `SectionID` int NOT NULL,
  `Grade` int NOT NULL,
  `EnrollmentDate` datetime NOT NULL,
  `Status` enum('Registered','Dropped') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  PRIMARY KEY (`EnrollmentID`) USING BTREE,
  INDEX `fk_StudentID`(`StudentID` ASC) USING BTREE,
  INDEX `fk_SectionID`(`SectionID` ASC) USING BTREE,
  CONSTRAINT `fk_SectionID` FOREIGN KEY (`SectionID`) REFERENCES `section` (`SectionID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_StudentID` FOREIGN KEY (`StudentID`) REFERENCES `student` (`StudentID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

