-- ----------------------------
-- Table structure for major
-- ----------------------------
DROP TABLE IF EXISTS `major`;
CREATE TABLE `major`  (
  `MajorID` int NOT NULL,
  `MajorName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `DepartmentID` int NULL DEFAULT NULL,
  PRIMARY KEY (`MajorID`) USING BTREE,
  INDEX `fk2_DepartmentID`(`DepartmentID` ASC) USING BTREE,
  CONSTRAINT `fk2_DepartmentID` FOREIGN KEY (`DepartmentID`) REFERENCES `department` (`DepartmentID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

