-- ----------------------------
-- Table structure for section
-- ----------------------------
DROP TABLE IF EXISTS `section`;
CREATE TABLE `section`  (
  `SectionID` int NOT NULL,
  `SectionNumber` int NOT NULL,
  `CourseID` int NOT NULL,
  `InstructorID` int NOT NULL,
  `SemesterID` int NOT NULL,
  `Capacity` int NOT NULL,
  `TimeSlot` datetime NOT NULL,
  `Location` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  PRIMARY KEY (`SectionID`) USING BTREE,
  INDEX `fk_InstructorID`(`InstructorID` ASC) USING BTREE,
  INDEX `fk_SemesterID`(`SemesterID` ASC) USING BTREE,
  CONSTRAINT `fk_InstructorID` FOREIGN KEY (`InstructorID`) REFERENCES `instructor` (`InstructorID`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_SemesterID` FOREIGN KEY (`SemesterID`) REFERENCES `semester` (`SemesterID`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

